  --   reader is told exactly that. A key whose boundary cannot be stated
  --   cannot be used to tell a reader what a vote meant. Writing the scope
  --   note for it is a vocabulary decision this wave was not asked to make and
  --   would be making alone, on one amendment.

  -- DECLINED on H.Amdt. 207 — gov_regulation:
  --   Refused by gov_regulation's out clause: an exemption from a Clean Air
  --   Act emission standard is a claim about what a particular rule should SAY
  --   for one sector, not about how many federal rules there are or how they
  --   are written and repealed. The out clause sends a sector claim to that
  --   sector's key, and the sector here is emissions.

END $$;

-- ────────────────────────────────────────────────────────────────────────────
-- VERIFICATION — scoped to THIS WAVE'S 7 roll calls and 7 measures.
-- Nothing below counts a session-wide or corpus-wide total. A guard that fails because
-- some other wave landed is a guard that gets deleted, so every count here is taken
-- over the named rolls and the named measure numbers only. The roll ids live in an
-- integer[] local rather than a temp table: a data-only migration that sorts after the
-- newest drizzle snapshot may not declare an object, and scripts/test-vr-corrections.mjs
-- reads any CREATE of a TABLE as a declaration regardless of how temporary it is.
-- ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  roll_ids integer[];
  measure_ids integer[];
  parent_ids integer[];
  n integer;
BEGIN
  SELECT array_agg(r.id ORDER BY r.id) INTO roll_ids FROM vr_rollcalls r
   WHERE r.chamber = 'house' AND (r.congress, r.session, r.roll_number) IN (
     (119, 1, 246), (119, 1, 248), (119, 1, 249), (119, 1, 251), (119, 1, 252), (119, 2, 148), (119, 2, 152)
   );
  SELECT array_agg(m.id ORDER BY m.id) INTO measure_ids FROM vr_measures m
   WHERE m.measure_type = 'amendment' AND m.congress = 119 AND m.chamber = 'house' AND m.number IN ('H.Amdt. 86', 'H.Amdt. 88', 'H.Amdt. 89', 'H.Amdt. 79', 'H.Amdt. 81', 'H.Amdt. 196', 'H.Amdt. 207');
  SELECT array_agg(m.id ORDER BY m.id) INTO parent_ids FROM vr_measures m
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.number IN ('H.R. 3838', 'H.R. 7567');

  IF coalesce(array_length(roll_ids, 1), 0) <> 7 THEN
    RAISE EXCEPTION 'Federal wave F9: expected 7 roll calls for this wave, found %', coalesce(array_length(roll_ids, 1), 0);
  END IF;
  IF coalesce(array_length(measure_ids, 1), 0) <> 7 THEN
    RAISE EXCEPTION 'Federal wave F9: expected 7 amendment measures for this wave, found %', coalesce(array_length(measure_ids, 1), 0);
  END IF;
  IF coalesce(array_length(parent_ids, 1), 0) <> 2 THEN
    RAISE EXCEPTION 'Federal wave F9: expected both parent vehicles on file, found %', coalesce(array_length(parent_ids, 1), 0);
  END IF;

  -- THE PARENT IS NOT DOUBLE-COUNTED. This is the guard the brief names first and it is
  -- asserted from both directions: no roll call written by this wave hangs off a parent,
  -- and every amendment roll hangs off the amendment it belongs to.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids) AND r.measure_id = ANY(parent_ids);
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % of this wave''s roll calls are filed against a parent vehicle rather than against the amendment. One instrument, one act.', n;
  END IF;
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids) AND NOT (r.measure_id = ANY(measure_ids));
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % of this wave''s roll calls are filed against a measure this wave did not write.', n;
  END IF;

  -- THE AMEND MAPS TO ITS SUBJECT, NOT TO ITS VEHICLE. Every issue row this wave writes
  -- sits on an amendment; the two vehicles hold exactly the issue rows they already held.
  SELECT count(*) INTO n FROM vr_measure_issues i WHERE i.measure_id = ANY(measure_ids);
  IF n <> 7 THEN
    RAISE EXCEPTION 'Federal wave F9: expected 7 issue rows on this wave''s amendments, found %', n;
  END IF;
  SELECT count(*) INTO n FROM vr_measure_issues i WHERE i.measure_id = ANY(measure_ids) AND NOT i.is_primary;
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % secondary issue row(s) appeared. Each amendment here is one subject and carries one PRIMARY row.', n;
  END IF;
  SELECT count(*) INTO n FROM vr_measure_issues i
   WHERE i.measure_id = ANY(parent_ids) AND i.issue_key IN (SELECT DISTINCT issue_key FROM vr_measure_issues WHERE measure_id = ANY(measure_ids))
     AND i.rationale LIKE '%Federal wave F9%';
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % issue row(s) written by this wave landed on a parent vehicle.', n;
  END IF;

  -- Only the four keys this wave argued for, and none of them new.
  SELECT count(*) INTO n FROM vr_measure_issues i WHERE i.measure_id = ANY(measure_ids)
     AND i.issue_key NOT IN ('climate_action', 'lgbtq_rights', 'states_federal_power', 'tough_on_crime');
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % issue row(s) carry a key outside the four this wave argued for.', n;
  END IF;

  -- Every issue row owes a rationale long enough to be an argument rather than a label.
  SELECT count(*) INTO n FROM vr_measure_issues i WHERE i.measure_id = ANY(measure_ids)
     AND (i.rationale IS NULL OR length(i.rationale) < 200);
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % issue row(s) carry no written rationale.', n;
  END IF;

  -- actionType stays in the closed vocabulary, and on an amendment roll it is 'amendment'.
  -- Never 'discharge', which the pack has never heard of, and never 'passage', which would
  -- claim this roll disposed of the parent bill.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids) AND r.action_type <> 'amendment';
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % roll(s) carry an action_type other than amendment.', n;
  END IF;

  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids);
  IF n <> 811 THEN
    RAISE EXCEPTION 'Federal wave F9: expected 811 member votes on this wave''s rolls, found %', n;
  END IF;

  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids)
     AND v.position NOT IN ('yea', 'nay', 'present', 'not_voting');
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % member vote(s) carry a position outside the closed vocabulary.', n;
  END IF;
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids)
     AND v.is_party IS NOT NULL AND v.is_party NOT IN ('with_party', 'against_party');
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % member vote(s) carry an is_party outside the closed vocabulary.', n;
  END IF;

  -- The tally is the chamber's, not the roster's. A House roll accounts for 425-441
  -- seats; anything near the roster's 116 attributable House slugs is the attributed
  -- subset masquerading as the chamber, which would publish a vote that never happened.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
       + coalesce((r.totals->>'present')::int, 0) + coalesce((r.totals->>'notVoting')::int, 0)
       NOT BETWEEN 425 AND 441;
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % roll(s) do not account for a full House.', n;
  END IF;

  -- F8's pull rule, in the migration as well as in the generator: the attributed set is a
  -- SUBSET of the chamber, so a yea+nay pool smaller than the attributed judged rows means
  -- the totals were recomputed from the rows.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
       < (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id = r.id AND v.position IN ('yea', 'nay'));
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % roll(s) have a yea+nay pool smaller than their attributed yea/nay rows.', n;
  END IF;

  -- Rule 11 on the amend roll, in the migration and not only in the harness.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids)
     AND 10 * least((r.totals->>'yea')::int, (r.totals->>'nay')::int)
         < (r.totals->>'yea')::int + (r.totals->>'nay')::int;
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % roll(s) fail rule 11 — the losing side is under a tenth of the yea+nay pool.', n;
  END IF;

  -- One instrument, one act: seven rolls, seven measures, no measure carrying two of them.
  SELECT count(*) INTO n FROM (SELECT measure_id FROM vr_rollcalls WHERE id = ANY(roll_ids) GROUP BY measure_id HAVING count(*) > 1) x;
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % measure(s) carry more than one of this wave''s rolls.', n;
  END IF;

  -- Each amendment hangs off its vehicle through parent_id, which is what the column is
  -- for, and no amendment points at another amendment.
  SELECT count(*) INTO n FROM vr_measures m WHERE m.id = ANY(measure_ids) AND NOT (m.parent_id = ANY(parent_ids));
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal wave F9: % amendment(s) do not hang off one of the two parent vehicles.', n;
  END IF;

  RAISE NOTICE 'Federal wave F9 verified: % amendment measures, % roll calls, % issue mappings, % member votes; 0 parent rolls, 0 parent issue rows, 0 new issue keys. Contested pool rebuilt at 51 (F7 said 54); 7 admitted, 44 refused in writing.',
    array_length(measure_ids, 1), array_length(roll_ids, 1),
    (SELECT count(*) FROM vr_measure_issues WHERE measure_id = ANY(measure_ids)),
    (SELECT count(*) FROM vr_member_votes WHERE rollcall_id = ANY(roll_ids));
END $$;
